function initMobilePagination() {
var MOBILE_BREAKPOINT = 768;
var HIDDEN_CLASS = 'cxb-b2b-pagination-hidden';
function adjustPagination() {
if (window.innerWidth > MOBILE_BREAKPOINT) {
$('.cxb-b2b-page-background-wrapper .nav-links').each(function() {
$(this).find('.' + HIDDEN_CLASS).removeClass(HIDDEN_CLASS);
$(this).find('.cxb-b2b-pagination-dots').remove();
$(this).children('.page-numbers.dots').removeClass(HIDDEN_CLASS);
});
return;
}
$('.cxb-b2b-page-background-wrapper .nav-links').each(function() {
var $navLinks = $(this);
var $allItems = $navLinks.children('.page-numbers');
$allItems.removeClass(HIDDEN_CLASS);
$navLinks.find('.cxb-b2b-pagination-dots').remove();
$navLinks.children('.page-numbers.dots').addClass(HIDDEN_CLASS);
var $prev = $allItems.filter('.prev');
var $next = $allItems.filter('.next');
var $current = $allItems.filter('.current');
var $numbered = $allItems.not('.prev, .next, .dots');
if ($numbered.length <= 1) return;
var containerWidth = $navLinks.parent().width();
var buttonGap = 4;
var fixedWidth = 0;
if ($prev.length) fixedWidth += $prev.outerWidth(true) + buttonGap;
if ($next.length) fixedWidth += $next.outerWidth(true) + buttonGap;
var singleBtnWidth = $current.length ? $current.outerWidth(true) : 32;
singleBtnWidth += buttonGap;
var dotsWidth = singleBtnWidth;
var availableWidth = containerWidth - fixedWidth - 8;
var currentIndex = $numbered.index($current);
var firstPage = $numbered.first();
var lastPage = $numbered.last();
var reservedWidth = singleBtnWidth * 3;
var remainingWidth = availableWidth - reservedWidth - (dotsWidth * 2);
var neighborsPerSide = Math.max(0, Math.floor((remainingWidth / singleBtnWidth) / 2));
var totalButtonsWidth = $numbered.length * singleBtnWidth;
if (totalButtonsWidth + fixedWidth <= containerWidth) return;
var keepIndices = {};
keepIndices[0] = true;
keepIndices[$numbered.length - 1] = true;
if (currentIndex >= 0) {
keepIndices[currentIndex] = true;
for (var n = 1; n <= neighborsPerSide; n++) {
if (currentIndex - n >= 0) keepIndices[currentIndex - n] = true;
if (currentIndex + n < $numbered.length) keepIndices[currentIndex + n] = true;
}
}
var prevWasHidden = false;
$numbered.each(function(i) {
if (!keepIndices[i]) {
$(this).addClass(HIDDEN_CLASS);
if (!prevWasHidden) {
var $dots = $('<span class="page-numbers cxb-b2b-pagination-dots" aria-hidden="true">&hellip;</span>');
$(this).before($dots);
}
prevWasHidden = true;
} else {
prevWasHidden = false;
}
});
});
}
adjustPagination();
var resizeTimer;
$(window).on('resize', function() {
clearTimeout(resizeTimer);
resizeTimer = setTimeout(adjustPagination, 150);
});
}
